WITH exploded AS (SELECT id, log_ts, level, status_code, attr_key, attr_value FROM app_logs LATERAL VIEW EXPLODE(context) li AS attr_key, attr_value) SELECT *, AVG(status_code) OVER (PARTITION BY level ORDER BY log_ts, id, attr_key ROWS BETWEEN 3 PRECEDING AND CURRENT ROW) AS status_code_avg_3, ROUND(status_code / SUM(status_code) OVER (PARTITION BY level), 4) AS status_code_share, NTILE(5) OVER (ORDER BY status_code DESC, id, attr_key) AS status_code_bucket, LAG(status_code, 1) OVER (PARTITION BY attr_key, level ORDER BY status_code, id, attr_key) AS prev_status_code FROM exploded;
